// === Tab: Heartstream ===
// Global parameters
const canvasW = 800;
const canvasH = 800;
const isDebugMode = false;

// Delay (ms) between hearts when mouse is held down
const particleThrottle = 50;

// Hold duration (ms) that qualifies as a long press
const longPressThrottle = 350;

// Variables-helpers
let lastParticleAt = -particleThrottle;
let hasThrottledParticle = false;
let lastTapAt;
let isTap = false;
let isLongPress = false;
let isPressed = false;
let pSet;
let doShowTapInstructions = true;
let doShowLongPressInstructions = true;

function setup() {
  createCanvas(canvasW, canvasH);
  pSet = new ParticleSet();
}

function draw() {
  background(240);

  if (doShowTapInstructions) {
    textSize(16);
    textAlign(CENTER, CENTER);
    text("Click to release a heart.", canvasW / 2, canvasH / 2 - 20);
  }
  if (doShowLongPressInstructions) {
    textSize(16);
    textAlign(CENTER, CENTER);
    text("Hold to unleash a stream.", canvasW / 2, canvasH / 2 + 20);
  }

  // Progress is time-based, not frame-based — ensures smooth animation regardless of frame rate
  const nowMs = millis();
  pSet.setNowMs(nowMs);

  // Custom click vs. long-press
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    if (isTap) {
      doShowTapInstructions = false;
      // A single tap lives one frame
      isTap = false;
    }
    if (!isPressed) {
      // Mouse is pressed down
      isPressed = true;
      isTap = true;
      lastTapAt = nowMs;
    }
    if ((!isLongPress) && (lastTapAt !== undefined) && ((nowMs - lastTapAt) >= longPressThrottle)) {
      isLongPress = true;
      doShowLongPressInstructions = false;
    }
  } else {
    isPressed = false;
    isTap = false;
    isLongPress = false;
  }

  // if (isDebugMode) {
  //   textSize(10);
  //   textAlign(LEFT, BOTTOM);
  //   text("nowMs: " + nowMs, 4, canvasH - 64);
  //   text("lastTapAt: " + lastTapAt, 4, canvasH - 49);
  //   text("isPressed: " + (isPressed ? "true" : "false"), 4, canvasH - 34);
  //   text("isTap: " + (isTap ? "true" : "false"), 4, canvasH - 19);
  //   text("isLongPress: " + (isLongPress ? "true" : "false"), 4, canvasH - 4);
  // }

  // Single click spawns one heart (not more than one per frame); hold spawns a throttled stream (not strictly one per frame)
  let doAddParticle = false;
  if (isTap) {
    pSet.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), nowMs));
  } else {
    if ((nowMs - lastParticleAt) >= particleThrottle) {  
      if (hasThrottledParticle) {
        doAddParticle = true;
        hasThrottledParticle = false;
      } else {
        if (isLongPress) {
          doAddParticle = true;
        }
      }
    } else if (isLongPress) {
      hasThrottledParticle = true;
    }
  }
  if (doAddParticle) {
    pSet.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), nowMs));
    lastParticleAt = nowMs;
  }

  pSet.render();
}

function drawHeart(x, y, size, fillColor, rotateAngle = 0) {
  // Using canvas transformation to rotate a single particle
  push();
  translate(x, y);
  rotate(rotateAngle);
  translate(-x, -y);
  fill(fillColor);
  strokeWeight(0);
  const offsetY = -size * 1/3;
  const originOffset = [0, size * 0.02];
  const bezierOffsets = [
    [size * 0.4, -size * 0.5],
    [size * 1.2, size * 0.5],
    [0, size * 0.95],
  ];
  beginShape();
  vertex(x + originOffset[0], y + originOffset[1] + offsetY);
  bezierVertex(
    x - bezierOffsets[0][0], y + bezierOffsets[0][1] + offsetY,
    x - bezierOffsets[1][0], y + bezierOffsets[1][1] + offsetY, 
    x - bezierOffsets[2][0], y + bezierOffsets[2][1] + offsetY,
  );
  bezierVertex(
    x + bezierOffsets[1][0], y + bezierOffsets[1][1] + offsetY,
    x + bezierOffsets[0][0], y + bezierOffsets[0][1] + offsetY, 
    x + originOffset[0], y + originOffset[1] + offsetY,
  );
  endShape(CLOSE);

  // Debug: points of Bezier curve
  // if (isDebugMode) {
  //   circle(x + originOffset[0], y + originOffset[1] + offsetY, 4);
  //   circle(x - bezierOffsets[0][0], y + bezierOffsets[0][1] + offsetY, 4);
  //   circle(x - bezierOffsets[1][0], y + bezierOffsets[1][1] + offsetY, 4);
  //   circle(x - bezierOffsets[2][0], y + bezierOffsets[2][1] + offsetY, 4);
  //   circle(x + bezierOffsets[1][0], y + bezierOffsets[1][1] + offsetY, 4);
  //   circle(x + bezierOffsets[0][0], y + bezierOffsets[0][1] + offsetY, 4);
  // }

  pop();
}

function strHsl(h, s, l, alphaVal = 1) {
  return `hsla(${h}, ${s}%, ${l}%, ${alphaVal})`;
}

function randomInt(a, b) {
  return floor(random(a, b + 1));
}

function randomAround(val, range) {
  return random(val - range, val + range);
}

function powErp(t, from, to, power = 1) {
  return from + (to - from) * pow(t, power);
}

function erpSizeFactor(t, maxFactor) {
  const erpPower = 0.25;
  const growLength = 0.02;
  const shrinkLength = 0.02;
  if (t <= growLength) {
    return powErp(t / growLength, 1, maxFactor, erpPower);
  } else if (t <= (growLength + shrinkLength)) {
    const subT = (t - growLength) / shrinkLength;
    return powErp(subT, maxFactor, 1, erpPower);
  } else {
    return 1 + 0.1 * sin((t - growLength + shrinkLength) * 10);
  }
}

class ParticleSet {
  constructor() {
    this.particles = [];
    this.nowMs = 0;
  }

  push(particle) {
    this.particles.unshift(particle);
  }

  render() {
    for (let i = this.particles.length - 1; i >= 0; i -= 1) {
      let particle = this.particles[i];
      particle.setNowMs(this.nowMs);
      particle.render();

      if (particle.isDead()) {
        this.particles.splice(i, 1);
      }
    }
  }

  setNowMs(ms) {
    this.nowMs = ms;
  }
}

class Particle {
  constructor(startX, startY, bornAt) {
    this.startX = startX;
    this.startY = startY;
    // Lifespan in ms
    this.lifespan = randomAround(3000, 500);
    // Each particle could have its own time dimension; all are synchronized with the global time by default
    this.nowMs = 0;
    this.bornAt = bornAt;
    // Base rotation phase
    this.angle = randomAround(-PI / 2, 0.2);
    // Total distance (px) a particle travels over its lifetime
    this.speed = this.lifespan * randomAround(0.1, 0.02);
    // Relative value
    this.size = randomAround(20, 2);
    this.baseColor = this.makeRandomHslColorTrio();
    // Vibration frequency: number of oscillation cycles over a particle's lifetime
    this.vibeRangeFreq = random(6);
    // Vibration amplitude (px)
    this.vibeRangeMax = random(15);
  }

  render() {
    this.drawAt(this.startX, this.startY);
  }

  drawAt(x, y) {
    const ageRatio = this.getAgeRatio();
    const vibeCoeff = this.vibeRangeMax * sin(ageRatio * PI * this.vibeRangeFreq);
    const vibeOffsetX = vibeCoeff * sin(-this.angle)
    const vibeOffsetY = vibeCoeff * cos(this.angle);
    //
    const ageSpeedCoeff = pow(ageRatio, 0.9) * this.speed;
    const offsetX = ageSpeedCoeff * cos(this.angle) + vibeOffsetX;
    var offsetY = ageSpeedCoeff * sin(this.angle) + vibeOffsetY;
    const alphaVal = 1 - ageRatio;
    const rotateOffset = 0.3 * sin(ageRatio * PI * 2);
    const rotateAngle = this.angle + PI / 2 + rotateOffset;
    //
    const fillColor = strHsl(this.baseColor[0], this.baseColor[1], this.baseColor[2], alphaVal);
    //
    const size = erpSizeFactor(ageRatio, 1.25) * this.size;
    drawHeart(x + offsetX, y + offsetY, size, fillColor, rotateAngle);
  }

  makeRandomHslColorTrio() {
    const h = randomInt(270, 360 + 10) % 360;
    const s = randomInt(70, 100);
    const l = randomInt(45, 65);
    return [h, s, l];
  }

  isDead() {
    return this.getAge() >= this.lifespan;
  }

  setNowMs(ms) {
    this.nowMs = ms;
  }

  getAge() {
    return this.nowMs - this.bornAt;
  }

  getAgeRatio() {
    return max(min(this.getAge() / this.lifespan, 1), 0);
  }
}

